    def __init__(self, dim=5):
        self.dim = dim
        # Prime-index classification for modular functional forms
        primes = [2, 3, 5, 7, 11, 13, 17, 19, 23]
        self.dimension_classes = []
        for i in range(dim):
            if i < len(primes) and (i+1) == primes[i]:
                # Prime-index dimensions get complex fractal structures
                self.dimension_classes.append('fractal')
            elif i % 3 == 0:
                # Multiples of 3 get chirp modulation
                self.dimension_classes.append('chirp')
            else:
                # Others get smooth basins
                self.dimension_classes.append('smooth')

        # Exponentially scaled parameters per dimension class
        self.smooth_params = {
            'base_amp': np.exp(np.linspace(-1.0, 0.5, dim)),
            'mod_scale': np.exp(np.linspace(-2.0, -0.5, dim))
        }
        self.chirp_params = {
            'base_amp': np.exp(np.linspace(0.0, 1.0, dim)),
            'mod_scale': np.exp(np.linspace(-1.0, 0.5, dim)),
            'chirp_rate': np.exp(np.linspace(-2.0, 0.0, dim))
        }
        self.fractal_params = {
            'base_amp': np.exp(np.linspace(1.0, 2.0, dim)),
            'mod_scale': np.exp(np.linspace(0.5, 1.5, dim)),
            'fractal_depth': np.exp(np.linspace(-0.5, 1.0, dim))
        }

    def _smooth_basin(self, x, base_amp, mod_scale):
        # Simple quadratic with Gaussian modulation
        return base_amp * (x**2) + mod_scale * np.exp(-0.3 * x**2) * np.sin(1.5 * np.pi * x)

    def _chirp_basin(self, x, base_amp, mod_scale, chirp_rate):
        # Position-dependent frequency modulation
        return base_amp * (x**2 + 0.1 * x**4) + mod_scale * np.exp(-0.5 * x**2) * \
               np.sin(3 * np.pi * x * (1 + chirp_rate * x))

    def _fractal_basin(self, x, base_amp, mod_scale, fractal_depth):
        # Weierstrass-Mandelbrot function with depth control
        K = int(5 + 2 * fractal_depth)
        C = 1.8 - 0.3 * fractal_depth
        L = 4.0 + 2.0 * fractal_depth

        sum_val = 0.0
        for k in range(K):
            sum_val += (C**k) * np.cos(L**(k+1) * np.pi * x)
        return base_amp * (x**2) + mod_scale * sum_val

    def f(self, x):
        total = 0.0
        for i in range(self.dim):
            xi = x[i]
            dim_class = self.dimension_classes[i]

            if dim_class == 'smooth':
                params = {
                    'base_amp': self.smooth_params['base_amp'][i],
                    'mod_scale': self.smooth_params['mod_scale'][i]
                }
                total += self._smooth_basin(xi, **params)

            elif dim_class == 'chirp':
                params = {
                    'base_amp': self.chirp_params['base_amp'][i],
                    'mod_scale': self.chirp_params['mod_scale'][i],
                    'chirp_rate': self.chirp_params['chirp_rate'][i]
                }
                total += self._chirp_basin(xi, **params)

            elif dim_class == 'fractal':
                params = {
                    'base_amp': self.fractal_params['base_amp'][i],
                    'mod_scale': self.fractal_params['mod_scale'][i],
                    'fractal_depth': self.fractal_params['fractal_depth'][i]
                }
                total += self._fractal_basin(xi, **params)

        return total

