        elif template_type == 2:
            # Sharp cusp basin (<0.5 units radius)
            power = max(4, int(dim_index / 1.8 + 3))
            return safe_xi**power * (1.0 + np.sin(safe_xi * dim_index)**2)

        else:  # template_type == 3
            # Chaotic micro-basin (<0.05 units radius)
            noise_freq = int(89 / float(dim_index % 7 + 1))
            return safe_xi**4 + (np.sin(noise_freq * xi)**6) * np.exp(-dim_index/20)

